ext('c12_geo_ch1',[
C("🏔️","प्राकृतिक और मानवीकृत पर्यावरण",["प्राकृतिक: भूमि, जल, जलवायु, वनस्पति","मानवीकृत: खेत, सड़क, नगर, बाँध","दोनों का आपसी संबंध","मनुष्य दोनों को बदलता है"],"मनुष्य के चारों ओर दो तरह का पर्यावरण होता है। एक प्राकृतिक, जैसे पहाड़, नदी, मिट्टी, वर्षा और जंगल। दूसरा मानवीकृत, जो इंसान ने ख़ुद बनाया, जैसे खेत, सड़क, मकान, नहर और शहर। गाँव का तालाब इन दोनों का मेल है, क्योंकि पानी प्रकृति का है, पर उसे गहरा करके घाट मनुष्य ने बनाया। मानव भूगोल इसी रिश्ते को पढ़ता है कि प्रकृति इंसान को कैसे प्रभावित करती है और इंसान प्रकृति को कैसे बदलता है।"),
C("🧊","नियतिवाद की समझ",["प्रकृति सर्वशक्तिमान मानी गई","जलवायु से जीवन तय","आदिम समाजों पर लागू","आलोचना: मनुष्य को निष्क्रिय माना"],"नियतिवाद कहता है कि मनुष्य के जीवन के सारे फ़ैसले प्रकृति तय करती है। जैसे बहुत ठंडे इलाक़े में लोग गर्म कपड़े पहनेंगे और शिकार करेंगे, रेगिस्तान में ऊँट पालेंगे। पुराने ज़माने में जब तकनीक कम थी, तब यह बात काफ़ी सही लगती थी। पर आज की आलोचना यह है कि इसमें इंसान की बुद्धि और मेहनत को भुला दिया गया। आज रेगिस्तान में भी नहरें और खेती हैं, इसलिए यह विचार अधूरा माना जाता है।"),
Q("नियतिवाद की मुख्य कमी क्या है?","यह मनुष्य की सोच, तकनीक और रचनात्मकता को महत्व नहीं देता","इस प्रश्न का उत्तर सोचिए... नियतिवाद ने प्रकृति को सब कुछ मान लिया। पर मनुष्य सिर्फ़ प्रकृति का दास नहीं है। वह तकनीक बनाता है, नहर खोदता है, सुरंग काटता है। इसलिए इस विचार की मुख्य कमी यह है कि यह मनुष्य की सोच, तकनीक और रचनात्मकता को महत्व नहीं देता। परीक्षा में एक वाक्य में यही लिखिए।"),
C("🌉","संभववाद की समझ",["प्रकृति अवसर देती है","चुनाव मनुष्य का","लेबल ब्लाश और फ़ेब्र","उदाहरण: नीदरलैंड के पोल्डर"],"संभववाद कहता है कि प्रकृति अवसर देती है और मनुष्य उसमें से चुनता है। वह चाहे तो उसी ज़मीन पर अलग-अलग काम कर सकता है। फ्रांस के भूगोलवेत्ता लेबल ब्लाश इस विचार के बड़े समर्थक थे। उदाहरण के लिए नीदरलैंड में लोगों ने समुद्र को पीछे धकेलकर पोल्डर बनाए और वहाँ खेती करते हैं। यानी प्रकृति ने नहीं कहा कि यहाँ ज़मीन बनाओ, मनुष्य ने ख़ुद फ़ैसला किया और किया।"),
Q("संभववाद का एक उदाहरण बताइए।","नीदरलैंड में समुद्र से ज़मीन निकालकर खेती करना (पोल्डर)","एक उदाहरण सोचिए... हमने नीदरलैंड की बात की थी। वहाँ कई जगह ज़मीन समुद्र के स्तर से नीचे है, फिर भी लोगों ने बाँध बनाकर समुद्र को रोका और खेती शुरू कर दी। इसे पोल्डर कहते हैं। यह संभववाद का बहुत अच्छा उदाहरण है, क्योंकि यहाँ मनुष्य ने प्रकृति की सीमा को अपनी तकनीक से बदल दिया।"),
C("🚦","नवनिश्चयवाद: बीच का रास्ता",["ग्रिफ़िथ टेलर का विचार","रुको और जाओ","पूरी तरह न रोक, न पूरी आज़ादी","विकास और पर्यावरण का संतुलन"],"नवनिश्चयवाद इन दोनों विचारों के बीच का रास्ता है। ग्रिफ़िथ टेलर ने इसे रुको और जाओ के सिद्धांत के रूप में समझाया। जैसे सड़क पर हरी बत्ती हो तो चलो, लाल हो तो रुको, और पीली हो तो सावधानी रखो। यानी मनुष्य प्रकृति की सीमाओं को देखकर विकास करे, न उन्हें बिल्कुल अनदेखा करे, न उनसे बिल्कुल बँधा रहे। आज का सतत विकास इसी सोच से मिलता है।"),
Q("रुको और जाओ का सिद्धांत किसने दिया?","ग्रिफ़िथ टेलर ने (नवनिश्चयवाद)","नाम याद कीजिए... यह सिद्धांत नवनिश्चयवाद से जुड़ा है। इसे ग्रिफ़िथ टेलर ने दिया। उन्होंने कहा कि मनुष्य को प्रकृति के संकेत देखकर चलना चाहिए। कहीं रुकना है, कहीं जाना है। यह नाम और सिद्धांत जोड़ी में याद रखिए, परीक्षा में अक्सर पूछा जाता है।"),
C("🗂️","मानव भूगोल की शाखाएँ विस्तार से",["सामाजिक: समाज और स्थान","आर्थिक: उद्योग, कृषि, व्यापार","राजनीतिक: राज्य और सीमाएँ","जनसंख्या, बस्ती, ऐतिहासिक"],"अब शाखाओं को एक-एक करके देखते हैं। सामाजिक भूगोल लोगों के समूहों और उनके रहने के ढंग को देखता है। आर्थिक भूगोल यह पढ़ता है कि लोग कमाते कैसे हैं, यानी कृषि, उद्योग और व्यापार। राजनीतिक भूगोल राज्यों, सीमाओं और चुनावी क्षेत्रों को देखता है। जनसंख्या भूगोल में आबादी का वितरण और घनत्व आता है, और बस्ती भूगोल गाँव और शहर के स्वरूप पर बात करता है।"),
Q("आर्थिक भूगोल किसका अध्ययन करता है?","मनुष्य की आर्थिक गतिविधियों, जैसे कृषि, उद्योग और व्यापार का","सोचिए... आर्थिक यानी रुपया-पैसा और रोज़ी-रोटी से जुड़ा। इसलिए यह मनुष्य की आर्थिक गतिविधियों का अध्ययन है, यानी कृषि, उद्योग, खनन और व्यापार। जैसे बिहार में धान की खेती या सूरत में कपड़ा उद्योग, ये सब आर्थिक भूगोल के उदाहरण हैं।"),
C("🛰️","आधुनिक तकनीक का उपयोग",["GIS से नक्शा और आँकड़े","GPS से सटीक स्थिति","उपग्रह चित्र","आपदा और योजना में सहायता"],"आज के भूगोल में तकनीक बहुत काम आती है। जी आई एस में नक्शे पर अलग-अलग आँकड़ों की परतें जोड़ी जाती हैं, जैसे सड़कें, आबादी और स्कूल। जी पी एस हमारी सही जगह बताता है, जैसे फ़ोन के नक्शे में। उपग्रह चित्रों से बाढ़ का क्षेत्र, जंगल की कटाई और शहर का फैलाव देखा जा सकता है। बिहार में बाढ़ के समय इन्हीं चित्रों से मदद पहुँचाने की योजना बनती है।"),
Q("जी आई एस का क्या उपयोग है?","नक्शे पर आँकड़ों की परतें जोड़कर विश्लेषण और योजना बनाना","अब इसे अपने शब्दों में कहिए... जी आई एस में हम एक ही नक्शे पर कई सूचनाएँ जोड़ते हैं, जैसे जनसंख्या, सड़क और बाढ़ का इलाक़ा। इससे अस्पताल या स्कूल कहाँ खोलना है, यह तय करना आसान होता है। सरल भाषा में, यह नक्शे और आँकड़ों का मेल है जो योजना बनाने में मदद करता है।"),
C("🏘️","अपने गाँव के उदाहरण",["प्राकृतिक: नदी, खेत, मौसम","मानवीकृत: पक्की सड़क, स्कूल","जनसंख्या और रोज़गार","प्रवास के कारण"],"अपने गाँव को ही मानव भूगोल की नज़र से देखिए। नदी, खेत और मौसम प्राकृतिक हैं। पक्की सड़क, स्कूल, बाज़ार और पानी की टंकी मानव ने बनाई है। कितने लोग गाँव में रहते हैं, वे क्या काम करते हैं और कितने लोग शहर कमाने जाते हैं, यह जनसंख्या और प्रवास से जुड़ा है। इस तरह किताब का हर विचार आपको आसपास की ज़िंदगी में दिख जाएगा।"),
Q("नियतिवाद, संभववाद और नवनिश्चयवाद में अंतर बताइए।","नियतिवाद: प्रकृति प्रधान; संभववाद: मनुष्य प्रधान; नवनिश्चयवाद: दोनों में संतुलन","तीनों को एक पंक्ति में बाँधिए... नियतिवाद में प्रकृति बड़ी है, संभववाद में मनुष्य बड़ा है, और नवनिश्चयवाद में दोनों का संतुलन है। चार अंक के प्रश्न में हर विचार के साथ एक विचारक का नाम और एक उदाहरण जोड़ देंगे तो पूरे अंक मिलेंगे।"),
C("✍️","उत्तर लिखने का तरीक़ा",["परिभाषा पहले","फिर शाखाएँ या विचार","एक उदाहरण","अंत में निष्कर्ष"],"दीर्घ उत्तर लिखते समय एक ढाँचा रखिए। पहले मानव भूगोल की सरल परिभाषा लिखिए। फिर विचारों या शाखाओं को बिंदुओं में बाँटिए। हर बिंदु के साथ एक छोटा उदाहरण लिखिए, जैसे नीदरलैंड का पोल्डर या अपने गाँव की नदी। अंत में एक पंक्ति का निष्कर्ष लिखिए कि मानव और पर्यावरण का रिश्ता दोनों ओर चलता है। साफ़ हैंडराइटिंग और शीर्षक रेखांकित करने से अंक बेहतर मिलते हैं।"),
],7)
